import{_ as o,o as e,c as s,a2 as r}from"./chunks/framework.DA69LXMH.js";const u=JSON.parse('{"title":"Portal do Jogador & Colaboração Segura","description":"","frontmatter":{},"headers":[],"relativePath":"recursos/colaboracao-e-portal.md","filePath":"recursos/colaboracao-e-portal.md"}'),n={name:"recursos/colaboracao-e-portal.md"};function t(i,a,d,l,c,p){return e(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="portal-do-jogador-colaboracao-segura" tabindex="-1">Portal do Jogador &amp; Colaboração Segura <a class="header-anchor" href="#portal-do-jogador-colaboracao-segura" aria-label="Permalink to &quot;Portal do Jogador &amp; Colaboração Segura&quot;">​</a></h1><p>O RPG de mesa é uma experiência coletiva. O <strong>EchoBot</strong> oferece um ambiente seguro e em tempo real para conectar seus jogadores ao universo da campanha sem comprometer o sigilo das anotações do Mestre.</p><hr><h2 id="📱-o-portal-do-jogador-player" tabindex="-1">📱 O Portal do Jogador (<code>/player</code>) <a class="header-anchor" href="#📱-o-portal-do-jogador-player" aria-label="Permalink to &quot;📱 O Portal do Jogador (\`/player\`)&quot;">​</a></h2><p>O Portal do Jogador é uma interface web dedicada, responsiva e mobile-first projetada para que os jogadores consultem informações e participem da construção do cenário:</p><ul><li><strong>Consulta à Lore Pública:</strong> Os jogadores podem explorar os artigos de compêndio, entender a história das cidades, ler sobre facções e consultar divindades.</li><li><strong>Omissão Automática de Segredos:</strong> O backend filtra 100% dos blocos de anotações confidenciais do Mestre (<em>GM Secrets</em>). Nenhum segredo ou ficha privada é transmitida para os jogadores.</li><li><strong>Exploração do Grafo de Lore:</strong> Visualização pública das relações conhecidas entre as entidades do mundo.</li><li><strong>Zero Necessidade de Instalação:</strong> Os jogadores acessam diretamente pelo navegador do celular ou computador, sem precisar baixar softwares ou criar contas.</li></ul><hr><h2 id="🛡️-firewall-do-mestre-seguranca-de-acesso-remoto" tabindex="-1">🛡️ Firewall do Mestre &amp; Segurança de Acesso Remoto <a class="header-anchor" href="#🛡️-firewall-do-mestre-seguranca-de-acesso-remoto" aria-label="Permalink to &quot;🛡️ Firewall do Mestre &amp; Segurança de Acesso Remoto&quot;">​</a></h2><p>Para garantir que ninguém na sua rede ou na internet acesse suas telas de mestre:</p><ul><li><strong>Isolamento Automático de Conexões:</strong> O middleware de segurança do EchoBot identifica quando uma requisição vem de fora do computador principal (<code>localhost</code>), seja via IP de rede local ou túnel remoto.</li><li><strong>Bloqueio de Painel Administrativo:</strong> Todas as rotas de gerenciamento (<code>/settings</code>, <code>/api/sessions</code>, <code>/logs</code>, rotas de chaves de API) são bloqueadas com código <code>403 Forbidden</code> para acessos externos.</li><li><strong>Redirecionamento Seguro:</strong> Qualquer tentativa de acesso ao domínio principal por um visitante externo é automaticamente redirecionada para <code>/player</code>.</li></ul><hr><h2 id="🌐-tunel-cloudflare-integrado-conexao-por-qr-code" tabindex="-1">🌐 Túnel Cloudflare Integrado &amp; Conexão por QR Code <a class="header-anchor" href="#🌐-tunel-cloudflare-integrado-conexao-por-qr-code" aria-label="Permalink to &quot;🌐 Túnel Cloudflare Integrado &amp; Conexão por QR Code&quot;">​</a></h2><p>Conectar seus amigos leva menos de 10 segundos:</p><ol><li>No menu superior ou dentro do Mundo, abra o modal de <strong>Colaboração com Jogadores</strong>.</li><li>Clique em <strong>Iniciar Túnel Cloudflare</strong>.</li><li>O EchoBot iniciará um túnel seguro temporário e exibirá: <ul><li>Um link público com criptografia HTTPS (ex: <code>https://seu-mundo.trycloudflare.com/player</code>).</li><li>Um <strong>QR Code na tela</strong>.</li></ul></li><li>Os jogadores presentes na mesa física podem apenas apontar a câmera do smartphone para o QR Code e entrar imediatamente no portal.</li></ol><hr><h2 id="✍️-sistema-de-propostas-moderacao-do-mestre" tabindex="-1">✍️ Sistema de Propostas &amp; Moderação do Mestre <a class="header-anchor" href="#✍️-sistema-de-propostas-moderacao-do-mestre" aria-label="Permalink to &quot;✍️ Sistema de Propostas &amp; Moderação do Mestre&quot;">​</a></h2><p>Estimule seus jogadores a enriquecerem o mundo criando NPCs, tavernas ou detalhes de seus históricos:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────┐             ┌──────────────────────────┐</span></span>
<span class="line"><span>│   Portal do Jogador      │             │   Painel do Mestre       │</span></span>
<span class="line"><span>│  (Celular / Navegador)   │             │   (Dashboard Local)      │</span></span>
<span class="line"><span>└────────────┬─────────────┘             └────────────┬─────────────┘</span></span>
<span class="line"><span>             │                                        │</span></span>
<span class="line"><span>             │ 1. Submete Proposta                    │</span></span>
<span class="line"><span>             ├───────────────────────────────────────►│ 2. Notificação WebSocket</span></span>
<span class="line"><span>             │                                        │</span></span>
<span class="line"><span>             │                                        │ 3. Abre Gaveta de Moderação</span></span>
<span class="line"><span>             │                                        │    com Visualizador de Diff</span></span>
<span class="line"><span>             │                                        │</span></span>
<span class="line"><span>             │                                        │ 4. Aprovar / Editar / Rejeitar</span></span>
<span class="line"><span>             │ 5. Atualização Instantânea da Wiki    │</span></span>
<span class="line"><span>             │◄───────────────────────────────────────┤</span></span></code></pre></div><ol><li><strong>Submissão:</strong> O jogador escreve um novo artigo de compêndio ou propõe alterações em um existente através do Portal.</li><li><strong>WebSocket em Tempo Real:</strong> O Mestre recebe um aviso visual instantâneo na interface.</li><li><strong>Visualizador de Diff:</strong> A gaveta de moderação do Mestre compara o texto atual com a proposta do jogador lado a lado com realce de adições e remoções (estilo Git).</li><li><strong>Decisão do Mestre:</strong> O Mestre pode: <ul><li><strong>Aprovar:</strong> O artigo é incorporado automaticamente à Wiki do Mundo e ao Grafo.</li><li><strong>Editar &amp; Aprovar:</strong> O Mestre ajusta o texto para adequar ao tom da campanha antes de publicar.</li><li><strong>Rejeitar:</strong> A proposta é descartada com feedback para o autor.</li></ul></li></ol>`,19)])])}const g=o(n,[["render",t]]);export{u as __pageData,g as default};
